    for(let i=0;i<8;i++){const a=Math.floor(i*dna.length/8),b=Math.max(a+1,Math.floor((i+1)*dna.length/8));let gc=0;for(let j=a;j<b&&j<dna.length;j++)if(dna[j]==='G'||dna[j]==='C')gc++;v.push(gc/Math.max(1,b-a));}
