    if(/ocean|marine|aquatic|water/.test(habitat))setting=tr('زیر آب، با ذرات معلق و نور فیلترشده با عمق','underwater, with suspended particles and depth-filtered light');
    else if(/shore|coast|wetland/.test(habitat))setting=tr('ساحل مرطوب/منطقهٔ جزرومدی، آب کم‌عمق و رسوب','wet shoreline/intertidal habitat, shallow water and sediment');
    else setting=tr('زیست‌بوم خشکی، بستر زمین و هوای آزاد','terrestrial habitat, ground contact and open air');
    if(age<1700)stage=tr('مرحلهٔ آغازین خط زمان در این مدل','early stage of this model timeline');else if(age<3900)stage=tr('مرحلهٔ عمدتاً اقیانوسی در این مدل','mostly oceanic-biosphere stage');else if(age<4070)stage=tr('مرحلهٔ گذار زیستگاه در مدل','habitat-transition stage');else if(age<4220)stage=tr('گسترش فرم‌های چندسلولی در مدل','multicellular-form expansion stage');else stage=tr('مرحلهٔ دیرهنگام خط زمان مدل','late stage of the model timeline');
